"""Generate the fake ~/.claude tree used by the core crate's behavior tests.

Run from anywhere:  uv run crates/core/tests/fixtures/gen_fixtures.py
The output (tests/fixtures/claude/) is committed; regenerate after editing this file.
Record shapes mirror real Claude Code 2.1.2xx transcripts (see kb/docs/claude-session-data-format.md).
"""

import json
import shutil
from datetime import datetime, timezone
from pathlib import Path

